public class Drivetrain extends SubsystemBase {
  private final Encoder m_encoder = new Encoder(0, 1);
  private final PIDController m_pid = new PIDController(0.5, 0.0, 0.0);

  public Drivetrain() {
    m_encoder.setDistancePerPulse(0.0005);
    SmartDashboard.putData("Drive PID", m_pid);
  }

  @Override
  public void periodic() {
    SmartDashboard.putData("Distance", m_encoder.getDistance());
  }
}
